describe('Login Form Keyboard Navigation Accessibility', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should navigate through login form fields using keyboard arrows', () => {
    // Focus on the username input field
    cy.get('[data-testid="username-input"]').focus();

    // Verify username input has focus
    cy.get('[data-testid="username-input"]').should('have.focus');

    // Press Tab to move to password input
    cy.get(':focus').type('{tab}');
    cy.get('[data-testid="password-input"]').should('have.focus');

    // Press Tab to move to remember me checkbox
    cy.get('[data-testid="password-input"]').type('{tab}');
    cy.get('[data-testid="remember-me-checkbox"]').should('have.focus');

    // Press Tab to move to submit button
    cy.get('[data-testid="remember-me-checkbox"]').type('{tab}');
    cy.get('[data-testid="login-button"]').should('have.focus');

    // Verify submit button is focusable
    cy.get('[data-testid="login-button"]').should('be.visible');

    // Press Enter to submit the form
    cy.get('[data-testid="login-button"]').type('{enter}');

    // Verify form submission was attempted
    cy.get('[data-testid="login-button"]').should('be.disabled', { timeout: 1000 });
    cy.get('[data-testid="login-button"]').should('have.attr', 'disabled');
  });

  it('should handle focus management when tabbing out of login form', () => {
    // Focus on username input
    cy.get('[data-testid="username-input"]').focus();

    // Press Tab to move to password input
    cy.get(':focus').type('{tab}');
    cy.get('[data-testid="password-input"]').should('have.focus');

    // Press Tab to move to remember me checkbox
    cy.get('[data-testid="password-input"]').type('{tab}');
    cy.get('[data-testid="remember-me-checkbox"]').should('have.focus');

    // Press Tab to move to submit button
    cy.get('[data-testid="remember-me-checkbox"]').type('{tab}');
    cy.get('[data-testid="login-button"]').should('have.focus');

    // Press Tab to wrap focus back to username input
    cy.get('[data-testid="login-button"]').type('{tab}');
    cy.get('[data-testid="username-input"]').should('have.focus');

    // Press Shift + Tab to move backwards
    cy.get('[data-testid="username-input"]').type('{shift}{tab}');
    cy.get('[data-testid="login-button"]').should('have.focus');

    // Verify focus is correctly managed and not lost
    cy.get('[data-testid="login-button"]').should('be.visible');
  });
});
